-- P10-E, P10-C security review R2: every SQLite location has `database` `main` and no schema
-- (ADR-0059 decision 6), so a location exception that is not scoped to one agent and target would
-- cover every SQLite file with the same table and column names. Such an exception covers SQLite
-- items only with `cross_target`, an explicit confirmation given by the administrator when the
-- exception is created (audited, `policy_exception.create`). Generated by drizzle-kit. A column with
-- a constant default is a catalog-only change; every existing row gets `false`, the strict meaning.
-- The CHECK (the flag only on a location exception that is not scoped to an agent and a target) is
-- validated in this migration on purpose: `policy_exceptions` holds administrator-written rows,
-- never a large table, and every existing row passes it (the flag is false). The runtime role keeps
-- its table-level privileges on `policy_exceptions` (migration 0003), which cover the new column.
ALTER TABLE "policy_exceptions" ADD COLUMN "cross_target" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "policy_exceptions" ADD CONSTRAINT "policy_exceptions_cross_target" CHECK (not "policy_exceptions"."cross_target" or ("policy_exceptions"."location" is not null and ("policy_exceptions"."agent_id" is null or "policy_exceptions"."target_id" is null)));
